        o_pend = {}

        m_tot = 0
        o_tot = 0
        m_last = 0

        m_open = False
        o_open = False

        for act in seq_actions:
            op = act['op']
            c = act.get('connection', 'main')
            k = act.get('key')
            v = act.get('value')

            if op == 'begin':
                if c == 'main': 
                    m_open = True
                    m_pend = {}
                else: 
                    o_open = True
                    o_pend = {}
            elif op == 'commit':
                if c == 'main':
                    for pk, pv in m_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
