                    m_pend = {}
                    m_open = False
                else:
                    for pk, pv in o_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    o_pend = {}
                    o_open = False
            elif op == 'rollback':
                if c == 'main': 
                    m_pend = {}
                    m_open = False
                else: 
                    o_pend = {}
                    o_open = False
            elif op == 'put':
                curr_val = None
                if c == 'main':
                    if k in m_pend:
                        curr_val = m_pend[k]
                    else:
                        curr_val = committed.get(k)
                else:
                    if k in o_pend:
                        curr_val = o_pend[k]
                    else:
                        curr_val = committed.get(k)

                success = False
                rows_changed = 0
                actual_trig = 0

                if curr_val is None:
                    success = True
                    rows_changed = 1
                    actual_trig = 1
                    if c == 'main': m_pend[k] = v
                    else: o_pend[k] = v
                else:
                    if strat == 'IGNORE':
                        success = False
                        rows_changed = 0
                        actual_trig = 0
                    elif strat == 'REPLACE':
                        success = True
                        rows_changed = 2
                        actual_trig = 1
