                        curr_val = o_pend[k]
                    else:
                        curr_val = committed.get(k)

                success = False
                rows_changed = 0
                actual_trig = 0

                if curr_val is None:
                    success = True
                    rows_changed = 1
                    actual_trig = 1
                    if c == 'main': m_pend[k] = v
                    else: o_pend[k] = v
                else:
