def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    goal = context.get("goal", "channel")
    actions = context.get("actions", [])

    def simulate_full(seq_actions, strat, trig, chan_mode):
        committed = {}
        m_pend = {}
        o_pend = {}

        m_tot = 0
        o_tot = 0
        m_last = 0

        for act in seq_actions:
            op = act['op']
            c = act.get('connection', 'main')
            k = act.get('key')
            v = act.get('value')

            if op == 'begin':
                if c == 'main': 
                    m_pend = {}
                else: 
                    o_pend = {}
            elif op == 'commit':
                if c == 'main':
                    for pk, pv in m_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    m_pend = {}
                else:
                    for pk, pv in o_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    o_pend = {}
            elif op == 'rollback':
                if c == 'main': 
                    m_pend = {}
                else: 
                    o_pend = {}
            elif op == 'put':
                curr_val = None
                if c == 'main':
                    if k in m_pend:
                        curr_val = m_pend[k]
                    else:
                        curr_val = committed.get(k)
                else:
                    if k in o_pend:
                        curr_val = o_pend[k]
                    else:
                        curr_val = committed.get(k)

                rows_changed = 0
                actual_trig = 0

                if curr_val is None:
                    rows_changed = 1
                    actual_trig = 1
                    if c == 'main': m_pend[k] = v
                    else: o_pend[k] = v
                else:
                    if strat == 'IGNORE':
                        rows_changed = 0
                        actual_trig = 0
                    elif strat == 'REPLACE':
                        rows_changed = 2
                        actual_trig = 1
                        if c == 'main': m_pend[k] = v
                        else: o_pend[k] = v
                    elif strat == 'UPSERT':
                        rows_changed = 1
                        actual_trig = 0
                        if c == 'main': m_pend[k] = v
                        else: o_pend[k] = v

                total_delta = rows_changed + (actual_trig if trig else 0)

                if c == 'main':
                    m_tot += total_delta
                    m_last = total_delta
                else:
                    o_tot += total_delta
            elif op == 'update':
                exists = False
                if c == 'main':
                    if k in m_pend:
                        exists = m_pend[k] is not None
                    else:
                        exists = k in committed
                else:
                    if k in o_pend:
                        exists = o_pend[k] is not None
                    else:
                        exists = k in committed

                if exists:
                    rows_changed = 1
                    actual_trig = 0
                    if c == 'main': m_pend[k] = v
                    else: o_pend[k] = v
                else:
                    rows_changed = 0
                    actual_trig = 0

                total_delta = rows_changed + (actual_trig if trig else 0)
                if c == 'main':
                    m_tot += total_delta
                    m_last = total_delta
                else:
                    o_tot += total_delta
            elif op == 'delete':
                exists = False
                if c == 'main':
                    if k in m_pend:
                        exists = m_pend[k] is not None
                    else:
                        exists = k in committed
                else:
                    if k in o_pend:
                        exists = o_pend[k] is not None
                    else:
                        exists = k in committed

                if exists:
                    rows_changed = 1
                    actual_trig = 0
                    if c == 'main': m_pend[k] = None
                    else: o_pend[k] = None
                else:
                    rows_changed = 0
                    actual_trig = 0

                total_delta = rows_changed + (actual_trig if trig else 0)
                if c == 'main':
                    m_tot += total_delta
                    m_last = total_delta
                else:
                    o_tot += total_delta

        res_count = len(committed)
        res_sum = sum(committed.values())

        ch_val = -1
        if chan_mode == 'MAIN_CHANGES': ch_val = m_last
        elif chan_mode == 'MAIN_TOTAL': ch_val = m_tot
        elif chan_mode == 'SUM_TOTAL': ch_val = m_tot + o_tot

        return ch_val, res_count, res_sum

    strategies = ['IGNORE', 'REPLACE', 'UPSERT']
    triggers = [True, False]
    channels = ['MAIN_CHANGES', 'MAIN_TOTAL', 'SUM_TOTAL']

