def investigate(context, acquire):
    history = acquire("history")
    receipts = []
    for r in history:
        if isinstance(r, dict) and "actions" in r and "observed" in r:
            receipts.append(r)

    def norm_actions(actions):
        out = []
        for a in actions:
            if not isinstance(a, dict):
                continue
            op = a.get("op")
            conn = a.get("connection", "main")
            if conn not in ("main", "other"):
                conn = "main"
            key = a.get("key")
            val = a.get("value")
            out.append((op, conn, key, val))
        return out

    def simulate(actions, pm, tg, cm):
        committed = {}
        in_tx = {"main": False, "other": False}
        pending = {"main": [], "other": []}
        changes = {"main": 0, "other": 0}
        total = {"main": 0, "other": 0}

        def apply_write(conn, op, key, val):
            if op == "put":
                existed = key in committed
                if pm == "ignore":
                    if existed:
                        return 0, 0
                    committed[key] = val
                    return 1, 1
                elif pm == "replace":
                    committed[key] = val
                    return 1, 1
                else:
                    committed[key] = val
                    if existed:
                        return 1, 0
                    return 1, 1
            elif op == "update":
                if key in committed:
                    committed[key] = val
                    return 1, 0
                return 0, 0
            elif op == "delete":
                if key in committed:
                    del committed[key]
                    return 1, 0
                return 0, 0
            return 0, 0

        for (op, conn, key, val) in actions:
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = []
            elif op == "commit":
                for (wop, wkey, wval) in pending[conn]:
                    d, t = apply_write(conn, wop, wkey, wval)
                    changes[conn] += d
                    total[conn] += d + t
                pending[conn] = []
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = []
                in_tx[conn] = False
            elif op in ("put", "update", "delete"):
                if in_tx[conn]:
                    pending[conn].append((op, key, val))
                else:
                    d, t = apply_write(conn, op, key, val)
                    changes[conn] += d
                    total[conn] += d + t

        if cm == "changes":
            ch = changes["main"]
        elif cm == "total_main":
            ch = total["main"]
        else:
            ch = total["main"] + total["other"]
        return ch, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    trigs = ["none", "insert"]
    channel_modes = ["changes", "total_main", "total_both"]

    candidates = []
    for pm in put_modes:
        for tg in trigs:
            for cm in channel_modes:
                candidates.append((pm, tg, cm))

    def check(cand, r):
        pm, tg, cm = cand
        acts = norm_actions(r["actions"])
        obs = r["observed"]
        ch, cnt, sm = simulate(acts, pm, tg, cm)
        if obs.get("channel") != ch:
            return False
        if obs.get("committed_count") != cnt:
            return False
        if obs.get("committed_sum") != sm:
            return False
        return True

    for r in receipts:
        candidates = [c for c in candidates if check(c, r)]

    goal = context.get("goal")
    actions = norm_actions(context.get("actions", []))

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for cand in candidates:
        pm, tg, cm = cand
        ch, cnt, sm = simulate(actions, pm, tg, cm)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

